mapper.sql:
WHERE u.deleted = 0
AND ( u.username LIKE CONCAT('%', #{kw}, '%') OR u.real_name LIKE CONCAT('%', #{kw}, '%') OR u.phone LIKE CONCAT('%', #{kw}, '%') )
AND u.status = #{status}

mapper.select:
SELECT
    COUNT(*) AS count
FROM sys_user
WHERE phone = #{phone}
    AND deleted = 0

    AND id != #{excludeId}

mapper.update:
UPDATE sys_user
SET status = #{status},
    update_time = #{updateTime}
WHERE id = #{id}
    AND deleted = 0

UPDATE sys_user
SET password = #{password},
    update_time = #{updateTime}
WHERE id = #{id}
    AND deleted = 0
